// Fault Detection: keep ESP32 data, ask laptop ML service.
const esp = msg.payload;
if (typeof esp !== 'object' || typeof esp.voltage !== 'number') return null;   // drop junk
msg.esp = esp;
// No ML while relay is tripped (load is off, current=0 would look like a fault) or sensors failed
if (esp.relay === 'TRIPPED' || esp.sensor_ok === false) { msg.statusCode = 0; return [null, msg]; }
msg.payload = { voltage: esp.voltage, current: esp.current, power: esp.power, temperature: esp.temperature };
msg.headers = { 'Content-Type': 'application/json' };
return [msg, null];

// Fuse edge (ESP32) + laptop ML, decide TRIP, publish to dashboard.
const esp = msg.esp;
const ml  = (msg.statusCode === 200 && msg.payload && typeof msg.payload.label === 'string') ? msg.payload : null;
const isFault = l => !!l && !['normal', 'off', 'n/a'].includes(l);
const ML_CONF = 0.6;      // laptop ML must be this sure
const NEED = 3;           // points needed to trip (5 s per reading)

let label = 'normal', conf = null, source = 'laptop_ml';
if (esp.relay === 'TRIPPED')      { label = 'tripped: ' + esp.trip_reason; conf = 1; source = 'esp32'; }
else if (esp.hard_rule)           { label = esp.hard_rule; conf = 1; source = 'hard_rule'; }
else if (ml && ml.label !== 'off') {
    label = ml.label; conf = ml.confidence;
    if (isFault(esp.edge_label) && esp.edge_label === ml.label) { source = 'edge+laptop agree'; conf = Math.max(conf, 0.9); }
} else if (!ml)                   { label = esp.edge_label; source = 'edge_only (ML service down)'; }

// Decision: both models flag a fault = 2 points, laptop ML alone (conf>=0.6) = 1 point,
// edge alone while ML service is down = 0.5 point (6 readings, same as ESP32 offline rule), otherwise reset.
let score = flow.get('score') || 0;
const mlFault = ml && isFault(ml.label) && ml.confidence >= ML_CONF;
const both = ml && isFault(ml.label) && isFault(esp.edge_label);
const edgeOnly = !ml && isFault(esp.edge_label);
score = esp.relay === 'TRIPPED' ? 0 : (both ? score + 2 : mlFault ? score + 1 : edgeOnly ? score + 0.5 : 0);
let cmd = null;
if (score >= NEED) { cmd = { payload: { cmd: 'TRIP', reason: label + ' (' + source + ')' } }; score = 0;
                     node.warn('TRIP sent: ' + cmd.payload.reason); }
flow.set('score', score);

const out = {
    timestamp: new Date().toISOString(),
    voltage: esp.voltage, current: esp.current, power: esp.power, temperature: esp.temperature,
    relay: esp.relay, edge_label: esp.edge_label, ml_label: ml ? ml.label : null,
    ml_probs: ml ? ml.probs : null, source, trip_score: score
};
if (!(ml && ml.label === 'off') && esp.edge_label !== 'off') out.prediction = { label, confidence: conf };
flow.set('latest', out);
return [{ payload: out }, cmd];
